#!/usr/bin/env python3
"""Collect ``result.json`` files into a single table (one row per run)."""

from __future__ import annotations

import argparse
import glob
import json
import os
from typing import Any, Dict, List


def flatten(prefix: str, obj: Any, out: Dict[str, Any]) -> None:
    if isinstance(obj, dict):
        for k, v in obj.items():
            flatten(f"{prefix}.{k}" if prefix else k, v, out)
    else:
        out[prefix] = obj


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--glob", default="runs/*/result.json")
    ap.add_argument("--out", default=None)
    args = ap.parse_args()

    rows: List[Dict[str, Any]] = []
    for path in sorted(glob.glob(args.glob)):
        with open(path) as fh:
            data = json.load(fh)
        row: Dict[str, Any] = {"run": os.path.dirname(path)}
        flatten("", data.get("config", {}), row)
        flatten("", {k: v for k, v in data.items() if k not in {"config", "logs", "tta_history"}}, row)
        rows.append(row)

    if not rows:
        print("no result.json found")
        return 1
    keys = sorted({k for r in rows for k in r})
    if args.out:
        with open(args.out, "w") as fh:
            json.dump(rows, fh, indent=2)
    try:
        import pandas as pd

        df = pd.DataFrame(rows)[keys]
        print(df.to_string(index=False))
    except Exception:
        for r in rows:
            print(json.dumps(r))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Adaptive tuning tests (Section 4.3)."""

import torch

from apt.tuning import adapter_importances, salient_adapter_names


class DummyAdapter:
    def __init__(self, importance: float, rank: int = 4, use_lora: bool = True):
        self.use_lora = use_lora
        self.rank = rank
        self._importance = importance

    def adapter_importance(self):
        return self._importance


class DummyTopo:
    def __init__(self, linears):
        self.linears = linears


def test_salient_adapters_take_the_top_half():
    topo = DummyTopo({f"l{i}": DummyAdapter(float(i)) for i in range(6)})
    names = salient_adapter_names(topo, top_fraction=0.5)
    assert set(names) == {"l3", "l4", "l5"}
    scores = adapter_importances(topo)
    assert scores.shape == (6,)


def test_adapters_without_lora_are_ignored():
    topo = DummyTopo(
        {
            "a": DummyAdapter(1.0),
            "b": DummyAdapter(2.0, use_lora=False),
            "c": DummyAdapter(3.0),
        }
    )
    assert set(salient_adapter_names(topo, 0.5)) == {"c"}

